(()=>{const q=new URLSearchParams(location.search),id=q.get('project')||q.get('id');if(q.get('embed')==='control'&&window.self!==window.top){const header=document.querySelector('header');if(header)header.hidden=true;return;}const works=[['simon','Colegio Simón Bolívar','f2aeb8e7-b8f7-4b03-be93-d7198c4f35b2'],['virgen','Virgen del Carmen','a41ecd24-5a8d-4f44-bc3a-53c1416ab5bb']];const a=document.createElement('a');a.href='/control.html'+(works.some(w=>w[2]===id)?'?project='+encodeURIComponent(id):'');a.textContent='Control de obras';a.style.cssText='padding:10px 16px;background:#ead095;color:#16384d;border-radius:6px;text-decoration:none;font-size:14px;font-weight:700;white-space:nowrap';(document.querySelector('header nav')||document.querySelector('header'))?.prepend(a);if(location.pathname==='/projects.html'){const box=document.createElement('section');box.setAttribute('aria-label','Acceso rápido al control de obras');box.style.cssText='display:flex;gap:16px;flex-wrap:wrap;padding:18px 0;margin-bottom:12px';for(const [key,title]of works){const link=document.createElement('a');link.href='/control.html?project='+key;link.style.cssText='flex:1;min-width:240px;background:#173f54;color:white;padding:22px;border-radius:12px;text-decoration:none;border-bottom:3px solid #d7ae55;font-size:19px;font-weight:650';const name=document.createElement('span');name.textContent=title;const sub=document.createElement('small');sub.textContent='Control de obra · Indicadores · Modelo 3D →';sub.style.cssText='display:block;margin-top:10px;color:#ead095;font-size:12px;font-weight:400';link.append(name,sub);box.append(link);}document.querySelector('main')?.prepend(box);}})();
